import { useCallback, useMemo, useRef, useState } from "react";
import { AgGridProvider, AgGridReact } from "ag-grid-react";
import type { ColDef, GetRowIdParams, ICellRendererParams } from "ag-grid-community";
import { AllEnterpriseModule } from "ag-grid-enterprise";

const modules = [AllEnterpriseModule];

interface Task {
  id: string;
  parentId?: string;
  name: string;
  owner: string;
  status: "Not started" | "In progress" | "Blocked" | "Done";
  due: string; // YYYY-MM-DD
  estimateHours: number;
}

const StatusPill = (p: ICellRendererParams<Task, Task["status"]>) =>
  p.value ? <span className={`status status-${p.value.replace(" ", "-").toLowerCase()}`}>{p.value}</span> : null;

export function ProjectGrid() {
  const gridRef = useRef<AgGridReact<Task>>(null);
  const [rowData] = useState<Task[]>([
    { id: "1", name: "Website relaunch", owner: "Sam", status: "In progress", due: "2026-11-30", estimateHours: 0 },
    { id: "2", parentId: "1", name: "Wireframes", owner: "Alex", status: "Done", due: "2026-10-10", estimateHours: 16 },
    { id: "3", parentId: "1", name: "Build pages", owner: "Taylor", status: "Not started", due: "2026-11-15", estimateHours: 40 },
  ]);

  const columnDefs = useMemo<ColDef<Task>[]>(() => [
    { field: "owner", editable: true, filter: "agSetColumnFilter",
      cellEditor: "agRichSelectCellEditor",
      cellEditorParams: { values: ["Alex", "Sam", "Taylor"] } },
    { field: "status", editable: true, cellRenderer: StatusPill,
      cellEditor: "agRichSelectCellEditor",
      cellEditorParams: { values: ["Not started", "In progress", "Blocked", "Done"] } },
    { field: "due", editable: true, cellDataType: "dateString", filter: "agDateColumnFilter" },
    { field: "estimateHours", editable: (p) => !p.node.group, aggFunc: "sum" },
  ], []);

  const autoGroupColumnDef = useMemo<ColDef<Task>>(() => ({
    headerName: "Task", field: "name", rowDrag: true, minWidth: 260,
  }), []);

  const getRowId = useCallback((p: GetRowIdParams<Task>) => p.data.id, []);

  return (
    <AgGridProvider modules={modules}>
      <button onClick={() => gridRef.current?.api.exportDataAsExcel()}>Export to Excel</button>
      <div style={{ height: 480 }}>
        <AgGridReact<Task>
          ref={gridRef}
          rowData={rowData}
          columnDefs={columnDefs}
          autoGroupColumnDef={autoGroupColumnDef}
          treeData
          treeDataParentIdField="parentId"
          getRowId={getRowId}
          groupDefaultExpanded={-1}
          rowDragManaged
          suppressMoveWhenRowDragging
          undoRedoCellEditing
        />
      </div>
    </AgGridProvider>
  );
}
